-- ============================================================
-- Schema PostgreSQL para Neon DB
-- Banco de Questões PNA · Manuais APNA 4ª Edição (2023)
-- ============================================================

-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. AREAS (Manuais APNA 4ª Edição)
CREATE TABLE areas (
    id          SERIAL PRIMARY KEY,
    nome        TEXT NOT NULL UNIQUE
);

-- 2. CAPITULOS
CREATE TABLE capitulos (
    id          SERIAL PRIMARY KEY,
    area_id     INTEGER NOT NULL REFERENCES areas(id),
    numero      INTEGER NOT NULL,
    nome        TEXT NOT NULL,
    UNIQUE(area_id, numero)
);

-- 3. SUBAREAS
CREATE TABLE subareas (
    id          SERIAL PRIMARY KEY,
    capitulo_id INTEGER NOT NULL REFERENCES capitulos(id),
    codigo      TEXT NOT NULL,
    nome        TEXT NOT NULL,
    UNIQUE(capitulo_id, codigo)
);

-- 4. QUESTOES
CREATE TABLE questoes (
    id                          TEXT PRIMARY KEY,  -- ex: "PNA2018-001"
    numero                      INTEGER,
    parte                       TEXT,
    ano_da_prova                INTEGER,
    nivel_de_dificuldade        TEXT,
    enunciado                   TEXT NOT NULL,
    resposta_correta            CHAR(1) NOT NULL,
    explicacao                  TEXT,
    doenca_ou_conjunto_de_doencas TEXT,
    subarea_id                  INTEGER REFERENCES subareas(id),
    created_at                  TIMESTAMPTZ DEFAULT NOW()
);

-- 5. ALTERNATIVAS
CREATE TABLE alternativas (
    id          SERIAL PRIMARY KEY,
    questao_id  TEXT NOT NULL REFERENCES questoes(id) ON DELETE CASCADE,
    letra       CHAR(1) NOT NULL,
    texto       TEXT NOT NULL,
    UNIQUE(questao_id, letra)
);

-- Índices para performance
CREATE INDEX idx_questoes_ano       ON questoes(ano_da_prova);
CREATE INDEX idx_questoes_subarea   ON questoes(subarea_id);
CREATE INDEX idx_questoes_nivel     ON questoes(nivel_de_dificuldade);
CREATE INDEX idx_alternativas_questao ON alternativas(questao_id);


