INSERT INTO alternativas (questao_id, letra, texto) VALUES
  ('SIM2023-11-080', 'A', 'Admissão no serviço de psiquiatéria para trabalhar a negação e a raiva inerentes a estáe processo.'),
  ('SIM2023-11-080', 'B', 'Solicitar a intervenção dos familiares para que autorizem o procedimento.'),
  ('SIM2023-11-080', 'C', 'Alta hospitalar.'),
  ('SIM2023-11-080', 'D', 'Interdição civil.'),
  ('SIM2023-11-080', 'E', 'Pedir apoio jurídico para que um juiz aprove o procedimento.'),
  ('SIM2023-11-081', 'A', 'Nova TC cranio-encefálica devido à suspeita de transformação hemorrágica de um acidente vascular cerebral de etiologia isquémica.'),
  ('SIM2023-11-081', 'B', 'Iniciar plasmaférese urgente.'),
  ('SIM2023-11-081', 'C', 'Iniciar o tratéamiento com glucocorticóides na dose de 1 mg/kg/dia.'),
  ('SIM2023-11-081', 'D', 'Investáigar o desencadeante do quadro de CID.'),
  ('SIM2023-11-081', 'E', 'Suspeitamos de mieloma mútliplo, deverá ser realizado um aspirado da médula ósea.'),
  ('SIM2023-11-082', 'A', 'Leucemia mielóide crónica.'),
  ('SIM2023-11-082', 'B', 'Leucemia promielocítica aguda.'),
  ('SIM2023-11-082', 'C', 'Leucemia monoblástica.'),
  ('SIM2023-11-082', 'D', 'Leucemia linfóide crónica.'),
  ('SIM2023-11-082', 'E', 'Leucemia linfóide aguda.'),
  ('SIM2023-11-083', 'A', 'Solicitar doseamento sérico das transaminases hepáticas e, se não estáiverem alteradas, a criança pode ter alta.'),
  ('SIM2023-11-083', 'B', 'Manter a criança em observação atéé que passem 4 horas desde a ingestáão, colher sangue para determinar a concentração de paracetamol e verificar se a N-acetilcisteína intravenosa estáá disponível, caso seja necessário adminstrá-la.'),
  ('SIM2023-11-083', 'C', 'Manter a criança em observação atéé que passem 4 horas desde a ingestáão, colher sangue para determinar a concentração de paracetamol e verificar se estáá disponível protamina, que é o antídoto necessário.'),
  ('SIM2023-11-083', 'D', 'Manter a criança em observação atéé que passem 6 horas desde a ingestáão, colher sangue para determinar a concentração de paracetamol e verificar se a atéropina, que é o antídoto necessário, estáá disponível.'),
  ('SIM2023-11-083', 'E', 'Entrar em contatéo com o coordenador da equipa de transplante hepático se for necessário transplante hepático.'),
  ('SIM2023-11-084', 'A', 'Sopro funcional.'),
  ('SIM2023-11-084', 'B', 'Estenose aórtica.'),
  ('SIM2023-11-084', 'C', 'Insuficiência aórtica.'),
  ('SIM2023-11-084', 'D', 'Miocardiopatéia hipertrófica.'),
  ('SIM2023-11-084', 'E', 'Comunicação interventricular.'),
  ('SIM2023-11-085', 'A', 'No lobo frontal.'),
  ('SIM2023-11-085', 'B', 'Na cápsula interna.'),
  ('SIM2023-11-085', 'C', 'No pedúnculo cerebral esquerdo.'),
  ('SIM2023-11-085', 'D', 'Na porção medial da protuberância caudal do lado esquerdo.'),
  ('SIM2023-11-085', 'E', 'No bulbo espinhal antes da decussação do fascículo cortico-espinhal direito.'),
  ('SIM2023-11-086', 'A', 'Dissulfiram.'),
  ('SIM2023-11-086', 'B', 'Clonazepam.'),
  ('SIM2023-11-086', 'C', 'Naloxona.'),
  ('SIM2023-11-086', 'D', 'Naltrexona.'),
  ('SIM2023-11-086', 'E', 'Bupropiom.'),
  ('SIM2023-11-087', 'A', 'O início de corticoterapia só deverá ser realizado após obtenção de exame de imagem que confirme a suspeita de compressão medular.'),
  ('SIM2023-11-087', 'B', 'Deve iniciar-se corticoterapia, mesmo que a radiografia de coluna lombar não tenha presença de compressão medular óbvia.'),
  ('SIM2023-11-087', 'C', 'Nestáe tipo de tumor, a verificar-se compressão medular, o facto de ser radioresistente pode ter implicações no manejo terapêutico.'),
  ('SIM2023-11-087', 'D', 'Se se verificar que o doente tem instabilidade vertebral, com deslocação da medula espinhal, deve realizar-se cirurgia e já não se pode realizar radioterapia.'),
  ('SIM2023-11-087', 'E', 'A topografia da possível compressão medular corresponde ao local onde mais frequentemente se localizam lesões causadoras destáe quadro.'),
  ('SIM2023-11-088', 'A', 'Antes de planear um tratéamento não é necessário realizar uma coronariografia.'),
  ('SIM2023-11-088', 'B', 'O prognóstico de vida destáe paciente sem qualquer tratéamento é de 10 anos, desde o momento do diagnóstico.'),
  ('SIM2023-11-088', 'C', 'Deve recomendar-se ao paciente evitar o exercício físico excessivo.'),
  ('SIM2023-11-088', 'D', 'Nestáe paciente é possível optar por tratéamento cirúrgico ou percutâneo pesando os riscos e comorbilidades do doente.'),
  ('SIM2023-11-088', 'E', 'Antes de planear um tratéamento não é necessário realizar um ecocardiograma.'),
