  ('SIM2023-19-041', 'D', 'Varicela hemorrágica.'),
  ('SIM2023-19-041', 'E', 'Doença de Kawasaki.'),
  ('SIM2023-19-042', 'A', 'Lesão biliar iatérogénica'),
