  ('SIM2023-20-119', 'B', 'Tromboembolismo pulmonar.'),
  ('SIM2023-20-119', 'C', 'Pneumonia por Legionella spp.'),
  ('SIM2023-20-119', 'D', 'Pneumomia por Rhodococcus equi.'),
  ('SIM2023-20-119', 'E', 'Tuberculose.'),
