INSERT INTO alternativas (questao_id, letra, texto) VALUES
  ('SIM2023-23-051', 'A', 'Core biopsy.'),
  ('SIM2023-23-051', 'B', 'Ecografia.'),
  ('SIM2023-23-051', 'C', 'Mamografia.'),
  ('SIM2023-23-051', 'D', 'Vigilância.'),
  ('SIM2023-23-051', 'E', 'Repetir avaliação em 6 meses.'),
  ('SIM2023-23-052', 'A', 'É a neoplasia linfoproliferatéiva mais comum nos doentes jovens.'),
  ('SIM2023-23-052', 'B', 'A maioria dos pacientes apresenta sintomas B.'),
  ('SIM2023-23-052', 'C', 'Em algumas ocasiões progride para outra forma histológica, mais agressiva.'),
  ('SIM2023-23-052', 'D', 'O atéingimento ósseo é frequente.'),
  ('SIM2023-23-052', 'E', 'A radioterapia é o tratéamento de eleição nos estáádios III e IV.'),
  ('SIM2023-23-053', 'A', 'O diagnóstico definitivo é feito mediante exame das fezes.'),
  ('SIM2023-23-053', 'B', 'É obrigatéório realizar um testáe respiratéório de H+.'),
  ('SIM2023-23-053', 'C', 'Iniciar prova terapêutica com leite extensamente hidrolisado e, em caso de melhoria clínica, assume-se o diagnóstico.'),
  ('SIM2023-23-053', 'D', 'Substituir o leite utilizado para um leite de soja.'),
  ('SIM2023-23-053', 'E', 'Provavelmente será um quadro transitório, a criança começará a tolerar o leite em 3-4 semanas.'),
  ('SIM2023-23-054', 'A', 'Avaliação neurológica utilizando-se a escala de Glasgow, avaliação pupilar, sinais de latéeralização e nível de lesão em medula (se houver). Reavaliar constantemente.'),
  ('SIM2023-23-054', 'B', 'Administrar FiO2 a 100%; exame físico do paciente com inspeção, palpação, percussão e auscultação, observando a dinâmica da caixa torácica. Tratéar as lesões com risco iminente de vida (pneumotórax aberto, pneumotórax hipertensivo, hemotórax maciço e tórax instável). Se disponível, monitorizar o doente com oximetria de pulso e eletrocardiografia contínua. Sempre reavaliar.'),
  ('SIM2023-23-054', 'C', 'Avaliação das vias aéreas com a imobilização cervical manual. Visualizar as vias aéreas, desobstruir a boca e a faringe, caso seja possível. Realizar manobras de desobstrução ("jaw thrust" e "chin lift"). Verificar se há permeabilidade da via e se estáa se manterá, na dúvida, garantir via aérea definitiva.'),
  ('SIM2023-23-054', 'D', 'Despir completamente o doente, evitar a hipotermia do paciente, aquecer o doente com cobertores ou dispositivos de aquecimento externo, ou infusão de líquidos aquecido.'),
  ('SIM2023-23-054', 'E', 'Avaliar PA, FC, pulso e diurese; avaliar a presença de hemorragia externa e de hemorragia interna. Conter as hemorragias visíveis com compressão.'),
