  ('SIM2023-23-055', 'B', 'Esofagite eosinofílica.'),
  ('SIM2023-23-055', 'C', 'Esofagite candidiásica.'),
  ('SIM2023-23-055', 'D', 'Esofagite por citomegalovírus.'),
  ('SIM2023-23-055', 'E', 'Adenocarcinoma do esófago.'),
