INSERT INTO alternativas (questao_id, letra, texto) VALUES
  ('SIM2023-24-102', 'A', 'Diminuir a ingestáão hídrica para 500 mL/dia.'),
  ('SIM2023-24-102', 'B', 'Iniciar um diurético.'),
  ('SIM2023-24-102', 'C', 'Medir a altura uterina, proceder à pesquisa do streptococcus beta-hemolítico do grupo B e recomendar a elevação dos membros inferiores.'),
  ('SIM2023-24-102', 'D', 'Recomendar o término da gravidez.'),
  ('SIM2023-24-102', 'E', 'Sugerir anticoagulação oral pelo elevado risco tromboembólico.'),
  ('SIM2023-24-103', 'A', 'Diminuição excessiva da pressão arterial.'),
  ('SIM2023-24-103', 'B', 'Hiperaldosteronismo hiperreninémico do diabético com resposta excessiva a IECA.'),
  ('SIM2023-24-103', 'C', 'Nefrite intersticial medicamentosa.'),
  ('SIM2023-24-103', 'D', 'Hipertensão renovascular.'),
  ('SIM2023-24-103', 'E', 'Nefropatéia diabética com evolução rápida por início de IECA.'),
  ('SIM2023-24-104', 'A', 'Diminuição dos níveis de testáosterona.'),
  ('SIM2023-24-104', 'B', 'Doença de Peyronie.'),
  ('SIM2023-24-104', 'C', 'Doença Microvascular.'),
  ('SIM2023-24-104', 'D', 'Lesão nervosa traumática periférica.'),
  ('SIM2023-24-104', 'E', 'Psicogénica.'),
  ('SIM2023-24-105', 'A', 'Devo, num ambiente tranquilo e apropriado, tentar compreender melhor quais as motivações matéernas para recusar aleitamento matéerno, devendo explicar e discutir com a mãe as suas vantagens.'),
  ('SIM2023-24-105', 'B', 'Não é necessário perceber quais as motivações matéernas para estáa decisão nem discutir as vantagens do aleitamento matéerno, uma vez que a mãe tem direito a estáa opção.'),
  ('SIM2023-24-105', 'C', 'Devo contactar imediatéamente a Comissão de Proteção de Crianças e Jovens (CPCJ).'),
  ('SIM2023-24-105', 'D', 'Devo apenas garantir que o recém-nascido estáá a cumprir um aporte hídrico total adequado.'),
  ('SIM2023-24-105', 'E', 'Devo dizer à mãe que o aleitamento matéerno é a única opção viável para a nutrição do recém- nascido.'),
  ('SIM2023-24-106', 'A', 'Deverá realizar um testáe de gravidez e, caso estáa se confirme, estáá aconselhada a realização da vacina da rubéola, rapidamente.'),
  ('SIM2023-24-106', 'B', 'Deverá realizar um testáe de gravidez e, caso estáa se confirme, deverá aguardar pelo terceiro trimestáre da gestáação para se vacinar.'),
  ('SIM2023-24-106', 'C', 'Deverá realizar um testáe de gravidez e, caso estáa não se confirme, deverá aguardar pelo menos 1 ano após a vacinação para tentar engravidar.'),
  ('SIM2023-24-106', 'D', 'Deverá realizar um testáe de gravidez e, caso estáa não se confirme, deverá aguardar pelo menos 1 mês após a vacinação para tentar engravidar.'),
  ('SIM2023-24-106', 'E', 'Está preconizada a vacinação independentemente de estáar ou não grávida.'),
  ('SIM2023-24-107', 'A', 'Deverão dirigir-se a um serviço de urgência hospitalar para realização de avaliação analítica.'),
  ('SIM2023-24-107', 'B', 'Vai para casa e se voltar a ter febre poderá controlar com paracetamol ou ibuprofeno.'),
  ('SIM2023-24-107', 'C', 'Deve evitar toma de anti-histamínicos.'),
  ('SIM2023-24-107', 'D', 'Recomendar iniciar aciclovir oral.'),
  ('SIM2023-24-107', 'E', 'Encaminhar os pais e a criança para um serviço de urgência hospitalar com cardiologia pediátrica de urgência para ser observado.'),
  ('SIM2023-24-108', 'A', 'Deverá iniciar ácido fólico 400 mcg/dia, 2 a 3 meses antes de suspender método contracetivo.'),
  ('SIM2023-24-108', 'B', 'Deverá iniciar ácido fólico 5 mg/dia, quando decidir suspender a pílula.'),
  ('SIM2023-24-108', 'C', 'É relevante proceder à investáigação da causa do aborto antes de tentar engravidar.'),
  ('SIM2023-24-108', 'D', 'Tem indicação para testáes invasivos (biópsia das vilosidades coriónicas ou amniocentese) dado os antecedentes.'),
  ('SIM2023-24-108', 'E', 'Deverá evitar a suplementação com iodo atéé ao diagnóstico de gravidez.'),
  ('SIM2023-24-109', 'A', 'Deve iniciar reposição hídrica e manter medidas de suporte sintomático.'),
  ('SIM2023-24-109', 'B', 'Deve iniciar tratéamento com ciprofloxacina.'),
  ('SIM2023-24-109', 'C', 'Deve colher hemoculturas e ficar internado para estáudo.'),
  ('SIM2023-24-109', 'D', 'Deve iniciar tratéamento com metronidazol.'),
  ('SIM2023-24-109', 'E', 'Deve colher coproculturas e ficar internado para estáudo.'),
  ('SIM2023-24-110', 'A', 'Determinar a satéuração periférica de oxigénio.'),
  ('SIM2023-24-110', 'B', 'Obter radiografia do tórax.'),
  ('SIM2023-24-110', 'C', 'Realizar gasometria arterial.'),
  ('SIM2023-24-110', 'D', 'Realizar estáudo microbiológico das secreções respiratéórias.'),
  ('SIM2023-24-110', 'E', 'Solicitar consulta de Pneumologia.'),
  ('SIM2023-24-111', 'A', 'Demência de Alzheimer.'),
  ('SIM2023-24-111', 'B', 'Demência Vascular.'),
  ('SIM2023-24-111', 'C', 'Demência de Corpos de Lewy.'),
  ('SIM2023-24-111', 'D', 'Demência Fronto-temporal.'),
  ('SIM2023-24-111', 'E', 'Pseudodemência.'),
  ('SIM2023-24-112', 'A', 'Começar por instituir terapêutica não farmacológica isolada, incluindo uma dieta pobre em sal, com adição de um IECA/ARA em caso de refractariedade.'),
  ('SIM2023-24-112', 'B', 'Iniciar terapêutica farmacológica com Enalapril 10 mg.'),
  ('SIM2023-24-112', 'C', 'Iniciar terapêutica farmacológica com Atenolol 50 mg.'),
  ('SIM2023-24-112', 'D', 'Iniciar terapêutica farmacológica com Clortalidona 12,5 mg.'),
  ('SIM2023-24-112', 'E', 'Adoptar uma estáratéégia conservadora e permissiva, dada a idade do doente.'),
  ('SIM2023-24-113', 'A', 'Colher estáudo analítico e iniciar antibioterapia empírica.'),
  ('SIM2023-24-113', 'B', 'Iniciar imediatéamente antibioterapia empírica com ceftriaxone.'),
  ('SIM2023-24-113', 'C', 'Colher estáudo analítico, estáudo da coagulação, hemocultura e realizar punção lombar. Posteriormente, iniciar antibioterapia empírica com ceftriaxone.'),
  ('SIM2023-24-113', 'D', 'Manter vigilância no serviço de urgência e reavaliar em pouco tempo.'),
  ('SIM2023-24-113', 'E', 'Colher estáudo analítico, estáudo da coagulação, hemocultura e realizar punção lombar. Posteriormente, iniciar antibioterapia empírica com ampicilina e cefotaxima.'),
  ('SIM2023-24-114', 'A', 'Colheita de três hemoculturas e urocultura e alta hospitalar com antibiótico empírico durante 1 semana (posteriormente ajustar de acordo com os resultados das culturas).'),
  ('SIM2023-24-114', 'B', 'Colheita de três hemoculturas e urocultura e posterior internamento com antibioterapia de largo espectro (Carbapenemos) durante 2 semanas (posteriormente ajustar de acordo com os resultados das culturas) .'),
  ('SIM2023-24-114', 'C', 'Colheita de três hemoculturas e urocultura, algaliação vesical e internamento com antibioterapia EV (posteriormente ajustar de acordo com resultados das culturas).'),
  ('SIM2023-24-114', 'D', 'Realização de resseção transuretral (RTU) da próstatéa desobstrutiva urgente.'),
  ('SIM2023-24-114', 'E', 'Colheita de três hemoculturas e urocultura, colocação de cistostomia suprapúbica e internamento com antibioterapia EV (posteriormente ajustar de acordo com resultados das culturas).'),
  ('SIM2023-24-115', 'A', 'Colheita de estáudo analítico e realização de tira-testáe urinária com urina colhida por saco coletor.'),
  ('SIM2023-24-115', 'B', 'Colheita de estáudo analítico e realização de sedimento urinário e urocultura com urina colhida por sonda vesical.'),
  ('SIM2023-24-115', 'C', 'Colheita de estáudo analítico e realização de tira-testáe urinária com urina colhida por algaliação.'),
  ('SIM2023-24-115', 'D', 'Colheita de estáudo analítico, realização de sedimento urinário e urocultura com urina colhida por sonda vesical e punção lombar.'),
  ('SIM2023-24-115', 'E', 'Alta com medidas sintomáticas e explicação de sinais de alarme.'),
