INSERT INTO alternativas (questao_id, letra, texto) VALUES
  ('SIM2023-28-003', 'B', 'A episiotomia é necessária em todos os partos vaginais.'),
  ('SIM2023-28-003', 'C', 'Esta grávida encontra-se em fase latéente de trabalho de parto e, portanto, tem indicação para internamento.'),
  ('SIM2023-28-003', 'D', 'A descrição do CTG remete-nos para um estáado fetal não tranquilizador e deverá ser realizada uma cesariana emergente.'),
  ('SIM2023-28-003', 'E', 'Se o grupo de sangue do bebé for Rh+ (positivo), a puérpera não precisa de fazer a imunoglobulina anti-D para profilaxia de isoimunização Rh.'),
  ('SIM2023-28-004', 'A', 'Atendendo ao bom desenvolvimento da criança, manter vigilância de rotina.'),
  ('SIM2023-28-004', 'B', 'A presença de enurese noturna já não é expectável nestáa idade, pelo que encaminha para consulta de pediatéria.'),
  ('SIM2023-28-004', 'C', 'É normal que a linguagem ainda não seja percetível nestáa idade, pelo que tranquiliza os pais.'),
  ('SIM2023-28-004', 'D', 'Uma linguagem impercetível nestáa idade constitui um sinal de alarme de desenvolvimento psicomotor nestáa idade, pelo que encaminha para consulta de pediatéria do desenvolvimento e terapia da fala.'),
  ('SIM2023-28-004', 'E', 'Com estáa idade, 10 horas de sono noturno é excessivo, pelo que aconselha a que acordem a criança mais cedo ou a deitá-la mais tarde.'),
  ('SIM2023-28-005', 'A', 'A hipótese diagnóstica mais provável é uma doença de lesões mínimas.'),
  ('SIM2023-28-005', 'B', 'A presença de hematéúria microscópica exclui a possibilidade de se tratéar de uma síndrome nefrótica.'),
  ('SIM2023-28-005', 'C', 'Deverá ser efetuada pesquisa do anticorpo para o recetor da fosfolipase-A2 (anti-PLA2R).'),
  ('SIM2023-28-005', 'D', 'A corticoterapia sistémica é o tratéamento de primeira linha.'),
  ('SIM2023-28-005', 'E', 'Os inibidores do eixo renina-angiotensina-aldosterrona (ex: IECA, ARA) poderão ser iniciados se a proteinúria se associar a agravamento da função renal.'),
  ('SIM2023-28-006', 'A', 'O Ecocardiograma transtorácico permite uma avaliação detalhada da válvula aórtica e da aorta ascendente, assumindo pela sua acessibilidade um papel central no diagnóstico de síndromes aórticos agudos.'),
  ('SIM2023-28-006', 'B', 'A realização de AngioTC estáá contraindicada, uma vez que pode agravar a pressão na parede aórtica, com risco de rutura da adventícia.'),
  ('SIM2023-28-006', 'C', 'Deve proceder-se à rápida administração de Heparina Não Fracionada, evitando a formação de trombos intramurais.'),
  ('SIM2023-28-006', 'D', 'Face à elevação da creatéinina, será lícito pensar num possível quadro de Disseção Aórtica tipo IIIa (classificação de DeBakey).'),
  ('SIM2023-28-006', 'E', 'No caso de se verificar uma disseção aórtica com atéingimento exclusivo da aorta descendente, podemos estáar perante uma disseção tipo B complicada (classificação de Stanford).'),
  ('SIM2023-28-007', 'A', 'Dado que o doente tem um cancro atéivo e estáá a fazer quimioterapia deverá ser internado para tratéamento com heparina não fracionada.'),
  ('SIM2023-28-007', 'B', 'A terapêutica com hipocoagulação deve ser realizada durante 1 semana e depois suspender, realizando-se ecografia venosa seriada para vigiar recorrência de trombose venosa profunda.'),
  ('SIM2023-28-007', 'C', 'A utilização dos novos anticoagulantes orais exige verificação de INR, pelo menos de forma quinzenal.'),
  ('SIM2023-28-007', 'D', 'Todos os tumores têm o mesmo risco de desenvolver trombose venosa, pelo que todos, incluindo estáe doente, devem realizar tromboprofilaxia primária em ambulatéório.'),
  ('SIM2023-28-007', 'E', 'Discutir com o doente o tratéamento com heparina baixo peso molecular (ex. enoxaparina) ou com um novo anticoagulante oral (ex. rivaroxabano).'),
  ('SIM2023-28-008', 'A', 'Pneumonia.'),
  ('SIM2023-28-008', 'B', 'Agudização de DPOC.'),
  ('SIM2023-28-008', 'C', 'Edema agudo do pulmão.'),
  ('SIM2023-28-008', 'D', 'Insuficiência cardíaca congestáiva de predomínio direito.'),
  ('SIM2023-28-008', 'E', 'Tromboembolismo pulmonar.'),
  ('SIM2023-28-009', 'A', 'Tratéa-se de uma hemorragia subaracnoideia, pelo que se deve iniciar nimodipina e completar estáudo com angiografia cerebral preferente.'),
  ('SIM2023-28-009', 'B', 'Alta hospitalar. A punção lombar foi traumática e tal falseia o resultado citológico e bioquímico do líquor. Provavelmente tratéa-se de uma cefaleia pós-coital.'),
  ('SIM2023-28-009', 'C', 'Iniciar aciclovir, pois poderia tratéar-se de uma encefalite herpética.'),
  ('SIM2023-28-009', 'D', 'Ainda há dúvidas quanto diagnóstico, pelo que se deve manter observação clínica e repetição da punção lombar em 24 horas.'),
  ('SIM2023-28-009', 'E', 'Não podemos afastar pequenas metástases não visíveis na TC que tenham sangrado, pelo que requer estáudo completar com RMN magnética.'),
  ('SIM2023-28-010', 'A', 'Realizar ecografia abdominal.'),
  ('SIM2023-28-010', 'B', 'Alta medicado com probiótico com Lactobacillus GG ou Saccharomyces boulardii e com indicação para reforço da hidratéação oral e evição da lactose, com vigilância dos sinais de alarme.'),
  ('SIM2023-28-010', 'C', 'Alta medicado com metoclopramida, probiótico com Lactobacillus GG ou Saccharomyces boulardii e indicação para reforço da hidratéação oral, com vigilância dos sinais de alarme.'),
  ('SIM2023-28-010', 'D', 'Alta medicado com probiótico com Lactobacillus GG ou Saccharomyces boulardii e com indicação para reforço da hidratéação oral, com vigilância dos sinais de alarme.'),
  ('SIM2023-28-010', 'E', 'Realizar tira testáe urinária.'),
  ('SIM2023-28-011', 'A', 'Síndrome cardio-renal.'),
  ('SIM2023-28-011', 'B', 'Amiloidose AA.'),
  ('SIM2023-28-011', 'C', 'Miocardite.'),
  ('SIM2023-28-011', 'D', 'Toxicidade por infliximab.'),
  ('SIM2023-28-011', 'E', 'Glomerulonefrite.'),
  ('SIM2023-28-012', 'A', 'Medicar com Cotrimoxazol oral 160/800 mg duas vezes ao dia.'),
  ('SIM2023-28-012', 'B', 'Amoxicilina-Ácido Clavulânico oral de 8/8h.'),
  ('SIM2023-28-012', 'C', 'Levofloxacina oral 500 mg uma vez ao dia.'),
  ('SIM2023-28-012', 'D', 'Colher urocultura e internar para antibioterapia endovenosa.'),
  ('SIM2023-28-012', 'E', 'Piperacilina-tazobactam 4,5 g de 8/8h.'),
  ('SIM2023-28-013', 'A', 'TC cerebral.'),
  ('SIM2023-28-013', 'B', 'Análise genética (pesquisa de instabilidade microsatéélite).'),
  ('SIM2023-28-013', 'C', 'Não são necessários estáudos adicionais, o diagnóstico é claro.'),
  ('SIM2023-28-013', 'D', 'Nova biópsia (provavelmente tratéa-se de um falso positivo).'),
  ('SIM2023-28-013', 'E', 'Estudo da doença celíaca, uma vez que estáá relacionada com estáe processo.'),
  ('SIM2023-28-014', 'A', 'Perda de visão.'),
  ('SIM2023-28-014', 'B', 'Aneurismas coronários.'),
  ('SIM2023-28-014', 'C', 'Lesão renal aguda.'),
  ('SIM2023-28-014', 'D', 'Tromboembolismo.'),
  ('SIM2023-28-014', 'E', 'Alterações neurológicas.'),
  ('SIM2023-28-015', 'A', 'Fibrinólise com tenecteplase.'),
  ('SIM2023-28-015', 'B', 'Anticoagulação oral.'),
  ('SIM2023-28-015', 'C', 'Aumentar a dose de heparina de baixo peso molecular, com a qual o doente já estáava medicado logo após admissão na unidade coronária.'),
  ('SIM2023-28-015', 'D', 'Angiografia urgente.'),
  ('SIM2023-28-015', 'E', 'Tratéamento com doses elevadas de ácido acetilsalicílico, face à suspeita de pericardite.'),
  ('SIM2023-28-016', 'A', 'Bruproprion.'),
  ('SIM2023-28-016', 'B', 'Aripiprazol.'),
  ('SIM2023-28-016', 'C', 'Venlafaxina.'),
  ('SIM2023-28-016', 'D', 'Lítio.'),
  ('SIM2023-28-016', 'E', 'Diazepam.'),
  ('SIM2023-28-017', 'A', '«Provavelmente tratéa-se apenas de icterícia fisiológica pelo que não há motivos de preocupação e poderá ter alta para casa.».'),
  ('SIM2023-28-017', 'B', '«Parece tratéar-se de uma icterícia do leite matéerno pelo que deve iniciar amamentação com leite de fórmula.».'),
  ('SIM2023-28-017', 'C', '«Parece tratéar-se de uma icterícia da amamentação e/ou icterícia fisiológica. É necessário confirmar o valor da bilirrubina, utilizando uma medição transcutânea, para avaliação da necessidade de tratéamento.».'),
  ('SIM2023-28-017', 'D', '«A probabilidade de se tratéar de uma icterícia fisiológica é baixa, porque habitualmente surge nas primeiras 24h de vida.».'),
  ('SIM2023-28-017', 'E', '«Tratéando-se, provavelmente, de icterícia fisiológica, dispensa-se o doseamento sérico de bilirrubina.».'),
