INSERT INTO alternativas (questao_id, letra, texto) VALUES
  ('SIM2023-28-103', 'B', 'Nestáa fase, estáa grávida ainda só deverá ter feito uma das ecografias necessárias na gravidez de baixo risco.'),
  ('SIM2023-28-103', 'C', 'A prova de tolerância a glicose oral faz parte das rotinas analíticas do 3º trimestáre.'),
  ('SIM2023-28-103', 'D', 'A ecografia morfológica deve ser realizada entre as 20 e as 22 semanas de gestáação.'),
  ('SIM2023-28-103', 'E', 'Deve realizar um ecocardiograma fetal no 2º ou 3º trimestáres de gestáação.'),
  ('SIM2023-28-104', 'A', 'Biópsia muscular normal.'),
  ('SIM2023-28-104', 'B', 'Níveis de CK normais no sangue.'),
  ('SIM2023-28-104', 'C', 'Electromiograma com atéividade muscular espontânea.'),
  ('SIM2023-28-104', 'D', 'Electromiograma com padrão de atéingimento neurogénico crónico.'),
  ('SIM2023-28-104', 'E', 'Ausência de resposta ao tratéamento com corticoides.'),
  ('SIM2023-28-105', 'A', 'Tratéa-se de um trabalho de parto precipitado.'),
  ('SIM2023-28-105', 'B', 'O início dos esforços expulsivos não indica que a grávida estáeja em dilatéação completa.'),
  ('SIM2023-28-105', 'C', 'A fase atéiva do trabalho de parto destáa grávida teve uma duração espectável para uma multípara.'),
  ('SIM2023-28-105', 'D', 'O trabalho de parto precipitado raramente se associa a complicações.'),
  ('SIM2023-28-105', 'E', 'A duração da fase atéiva do trabalho de parto é independente da paridade.'),
  ('SIM2023-28-106', 'A', 'O quadro clínico supracitado é compatéível com uma esclerite sectorial.'),
  ('SIM2023-28-106', 'B', 'O quadro clínico supracitado é compatéível com um pterígio temporal.'),
  ('SIM2023-28-106', 'C', 'O quadro clínico supracitado é compatéível com uma episclerite setorial.'),
  ('SIM2023-28-106', 'D', 'O quadro clínico supracitado é compatéível com uma pinguécula temporal.'),
  ('SIM2023-28-106', 'E', 'O quadro clínico supracitado é compatéível com uma esclerite e raramente estáá associada a causa sistémica.'),
  ('SIM2023-28-107', 'A', 'Deve realizar um ecocardiograma transtorácico.'),
  ('SIM2023-28-107', 'B', 'O quadro deve ser encarado como agudização da asma, sem necessidade de mais estáudos complementares.'),
  ('SIM2023-28-107', 'C', 'Deve fazer a prova de Mantoux.'),
  ('SIM2023-28-107', 'D', 'Deve realizar ECG, gasimetria, radiografia de tórax e antigenúrias para S. pneumonia e Legionella pneumophila.'),
  ('SIM2023-28-107', 'E', 'Deve realizar broncofibroscopia com análise do lavado broncoalveolar.'),
  ('SIM2023-28-108', 'A', 'O mecanismo de desnutrição mais provável é o défice de aporte calórico, configurando uma muito provável situação de marasmo que requer uma intervenção urgente.'),
  ('SIM2023-28-108', 'B', 'Para melhor avaliar o estáado nutricional destáa doente, dever-se-iam dosear os marcadores de função renal, tempo de protrombina, albumina e enzimas musculares.'),
  ('SIM2023-28-108', 'C', 'A ausência de edemas aponta para uma desnutrição predominantemente proteica, devendo questáionar-se a doente sobre a ingestáão de alimentos ricos em proteína.'),
  ('SIM2023-28-108', 'D', 'Analiticamente, seria de esperar uma hipoalbuminemia grave, bem como uma diminuição marcada das proteínas totais, transferrina e vitaminas do complexo B.'),
  ('SIM2023-28-108', 'E', 'Seria pertinente dosear marcadores inflamatéórios, já que a doente apresenta um quadro sugestáivo de caquexia, provavelmente secundária a uma doença inflamatéória não diagnosticada.'),
  ('SIM2023-28-109', 'A', 'AngioTAC pulmonar.'),
  ('SIM2023-28-109', 'B', 'PCR de exsudado nasofaríngeo.'),
  ('SIM2023-28-109', 'C', 'Serologia.'),
  ('SIM2023-28-109', 'D', 'Eletrocardiograma.'),
  ('SIM2023-28-109', 'E', 'TAC tóracico.'),
  ('SIM2023-28-110', 'A', 'Iniciar quelante de ferro com penicilamina.'),
  ('SIM2023-28-110', 'B', 'Pedir biópsia hepática para exclusão de cirrose.'),
  ('SIM2023-28-110', 'C', 'Pedir ecografia abdominal para exclusão de carcinoma hepatéocelular.'),
  ('SIM2023-28-110', 'D', 'Realizar flebotomia.'),
