-- ============================================================
-- VIEWS ÚTEIS PARA O FRONTEND / API
-- ============================================================

-- View completa de questões com join de área, capítulo e subárea
CREATE OR REPLACE VIEW questoes_completas AS
SELECT
    q.id,
    q.numero,
    q.parte,
    q.ano_da_prova,
    q.nivel_de_dificuldade,
    q.enunciado,
    q.resposta_correta,
    q.explicacao,
    q.doenca_ou_conjunto_de_doencas,
    a.nome  AS area,
    c.numero AS capitulo_numero,
    c.nome  AS capitulo_nome,
    s.codigo AS subarea_codigo,
    s.nome  AS subarea
FROM questoes q
JOIN subareas  s ON q.subarea_id  = s.id
JOIN capitulos c ON s.capitulo_id = c.id
JOIN areas     a ON c.area_id     = a.id;

-- View de estatísticas por área
CREATE OR REPLACE VIEW stats_por_area AS
SELECT
    a.nome AS area,
    COUNT(q.id) AS total_questoes,
    COUNT(DISTINCT q.ano_da_prova) AS anos_abrangidos,
    MIN(q.ano_da_prova) AS primeiro_ano,
    MAX(q.ano_da_prova) AS ultimo_ano
FROM questoes q
JOIN subareas  s ON q.subarea_id  = s.id
JOIN capitulos c ON s.capitulo_id = c.id
JOIN areas     a ON c.area_id     = a.id
GROUP BY a.nome
ORDER BY total_questoes DESC;

-- View de estatísticas por capítulo
CREATE OR REPLACE VIEW stats_por_capitulo AS
SELECT
    a.nome  AS area,
    c.numero AS capitulo_numero,
    c.nome  AS capitulo_nome,
    COUNT(q.id) AS total_questoes
FROM questoes q
JOIN subareas  s ON q.subarea_id  = s.id
JOIN capitulos c ON s.capitulo_id = c.id
JOIN areas     a ON c.area_id     = a.id
GROUP BY a.nome, c.numero, c.nome
ORDER BY a.nome, c.numero;

-- Função útil: buscar questões aleatórias por área e nível
CREATE OR REPLACE FUNCTION get_questoes_aleatorias(
    p_area TEXT DEFAULT NULL,
    p_nivel TEXT DEFAULT NULL,
    p_ano INTEGER DEFAULT NULL,
    p_limit INTEGER DEFAULT 10
)
RETURNS TABLE (
    id TEXT, numero INTEGER, parte TEXT, ano_da_prova INTEGER,
    nivel_de_dificuldade TEXT, enunciado TEXT, resposta_correta CHAR(1),
    explicacao TEXT, doenca_ou_conjunto_de_doencas TEXT,
    area TEXT, capitulo_nome TEXT, subarea TEXT
) AS 
BEGIN
    RETURN QUERY
    SELECT
        q.id, q.numero, q.parte, q.ano_da_prova,
        q.nivel_de_dificuldade, q.enunciado, q.resposta_correta,
        q.explicacao, q.doenca_ou_conjunto_de_doencas,
        a.nome, c.nome, s.nome
    FROM questoes q
    JOIN subareas  s ON q.subarea_id  = s.id
    JOIN capitulos c ON s.capitulo_id = c.id
    JOIN areas     a ON c.area_id     = a.id
    WHERE (p_area  IS NULL OR a.nome = p_area)
      AND (p_nivel IS NULL OR q.nivel_de_dificuldade = p_nivel)
      AND (p_ano   IS NULL OR q.ano_da_prova = p_ano)
    ORDER BY RANDOM()
    LIMIT p_limit;
END;
 LANGUAGE plpgsql;

